using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;

namespace Verso.Application.Documents;

/// <summary>
/// Where document bytes live (plan §2, §7). Keys are generated by Verso (<see cref="DocumentKeys"/>), never taken
/// from input. The MVP adapter is the local file system; production targets are an open decision (plan D6).
/// Only the Worker writes.
/// </summary>
public interface IDocumentStore
{
    /// <summary>Recorded on each document, so a later adapter change can still find older documents.</summary>
    string Provider { get; }

    /// <summary>Writes the whole content atomically, replacing an existing object with the same key.</summary>
    Task WriteAsync(string key, byte[] content, CancellationToken ct);

    /// <summary>The content, or null when there is no object with that key.</summary>
    Task<byte[]?> ReadAsync(string key, CancellationToken ct);

    /// <summary>Deletes the object if it exists.</summary>
    Task DeleteAsync(string key, CancellationToken ct);
}

public static class DocumentKeys
{
    /// <summary>Deterministic per execution and node, so a re-run overwrites instead of leaving a second copy.</summary>
    public static string Staging(Guid executionId, string nodeId) => $"staging/{executionId:N}/{nodeId}.pdf";

    /// <summary>Deterministic per document (dated by its creation, not by when archiving ran).</summary>
    public static string Archive(Guid documentId, DateTimeOffset createdAt) =>
        $"archive/{createdAt.UtcDateTime:yyyy}/{createdAt.UtcDateTime:MM}/{documentId:N}.pdf";

    public static string Sha256Hex(byte[] content) => Convert.ToHexStringLower(SHA256.HashData(content));
}

/// <summary>Turns resolved name patterns into safe file names and archive folder paths.</summary>
public static partial class DocumentNames
{
    public const int MaxFileNameLength = 200;
    public const int MaxFolderPathLength = 300;

    [GeneratedRegex(@"[^A-Za-z0-9 ._()\-]")]
    private static partial Regex UnsafeFileNameChars();

    [GeneratedRegex(@"[^A-Za-z0-9 ._\-]")]
    private static partial Regex UnsafeSegmentChars();

    /// <summary>Letters, digits, space, <c>. _ ( ) -</c> only; always ends in <c>.pdf</c>; "document.pdf" when nothing is left.</summary>
    public static string FileName(string resolved)
    {
        var name = UnsafeFileNameChars().Replace(resolved.Normalize(NormalizationForm.FormC), "_").TrimEnd(' ', '.');
        if (name.EndsWith(".pdf", StringComparison.OrdinalIgnoreCase))
        {
            name = name[..^4];
        }

        name = name.Trim(' ', '.');
        if (name.Length == 0 || name.All(c => c == '_'))
        {
            name = "document";
        }

        name = name[..Math.Min(name.Length, MaxFileNameLength - 4)];
        return name + ".pdf";
    }

    /// <summary>
    /// Segments separated by <c>/</c>; each keeps letters, digits, space and <c>. _ -</c> (others become <c>_</c>),
    /// without leading or trailing dots, so <c>..</c> can't appear. Empty segments are dropped.
    /// </summary>
    public static string FolderPath(string resolved)
    {
        var segments = resolved.Replace('\\', '/').Split('/')
            .Select(s => UnsafeSegmentChars().Replace(s.Normalize(NormalizationForm.FormC), "_").Trim(' ', '.'))
            .Where(s => s.Length > 0);
        var path = string.Join('/', segments);
        return path.Length <= MaxFolderPathLength ? path : path[..MaxFolderPathLength].TrimEnd('/', ' ', '.');
    }
}
